// Characterization tests: pin the current client-visible behavior of the HTTP API,
// including quirks (e.g. 200 for unknown orders). Change expectations only deliberately.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 3, pear: 2.5, tv: 101, hundred: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const create = async (items) => {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order with 201, JSON content type and computed total', async () => {
  const items = [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 2 }]
  const { res, body } = await create(items)
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 11)
})

test('ids are strings and increment sequentially', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body
  const b = (await create([{ sku: 'apple', qty: 1 }])).body
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to whole euros', async () => {
  assert.equal((await create([{ sku: 'pear', qty: 1 }])).body.total, 2)
  assert.equal((await create([{ sku: 'pear', qty: 3 }])).body.total, 7)
})

test('no discount at exactly 100', async () => {
  assert.equal((await create([{ sku: 'hundred', qty: 1 }])).body.total, 100)
})

test('10% discount when total is above 100, then floored', async () => {
  assert.equal((await create([{ sku: 'tv', qty: 1 }])).body.total, 90) // 90.9
  assert.equal((await create([{ sku: 'hundred', qty: 2 }])).body.total, 180)
})

test('extra item fields are echoed back unchanged', async () => {
  const items = [{ sku: 'apple', qty: 1, note: 'gift' }]
  assert.deepEqual((await create(items)).body.items, items)
})

test('GET /orders/:id returns the created order with 200', async () => {
  const created = (await create([{ sku: 'apple', qty: 4 }])).body
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with { error: "not found" } (quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('a failed creation does not consume an id or create an order', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body
  await post({ items: [] })
  const b = (await create([{ sku: 'apple', qty: 1 }])).body
  assert.equal(Number(b.id), Number(a.id) + 1)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'apple' }],
  ['empty body', undefined, ''],
  ['malformed JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders with ${name} -> 400 { error: "items required" }`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.match(res.headers.get('content-type'), /^application\/json/)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('unknown routes and methods -> 404 { error: "no route" }', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'],
    ['POST', '/orders/1'], ['GET', '/orders/1/items'], ['GET', '/other'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' }, `${method} ${path}`)
  }
})

test('query strings are ignored when routing', async () => {
  const created = (await create([{ sku: 'apple', qty: 1 }])).body
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
